// GAIA's Air Mail city stamps, generated by scripts/fetch-briefing-editions.mjs.
// The art is hosted on GAIA's Cloudinary; only the catalogue is vendored.

import stampCities from './stamp-cities.json';

export interface StampCity {
	slug: string;
	name: string;
	country: string;
	/** ISO 3166 alpha-2, lowercase */
	countryCode: string;
	/** The asset key the postal template reads this city's art from. */
	assetKey: string;
	url: string;
	/** The country's own air-mail phrase; empty when it is "Par Avion" / "By Air Mail". */
	air: string;
}

export const STAMP_CITIES: StampCity[] = stampCities;

/** The stamp art trimmed to its perforations, resized and compressed (AVIF: ~3x smaller than WebP). */
export const stampImage = (city: StampCity, width: number) =>
	city.url.replace('/upload/', `/upload/e_trim/w_${width},q_auto:eco,f_avif/`);
